if (n == 0) return 1.0;

// For small n, use the direct formula alpha^n / sqrt(n!)
// We use a threshold (e.g., 100) where factorial starts to risk overflow 
// or where Stirling's approximation becomes highly accurate.
if (n < 100) {
    return std::pow(alpha, n) / std::sqrt(boost::math::factorial<double>(n));
}

// For large n, use Stirling's approximation: n! ~ sqrt(2*pi*n) * (n/e)^n
// The coefficient is alpha^n / sqrt(n!)
// ln(coeff) = n*ln(alpha) - 0.5 * ln(n!)
// ln(n!) approx 0.5*ln(2*pi*n) + n*ln(n) - n
// We calculate the magnitude and phase separately to avoid overflow in pow()
double abs_alpha = std::abs(alpha);
double phase_alpha = std::arg(alpha);

double ln_n_fact = 0.5 * std::log(2.0 * M_PI * n) + n * std::log((double)n) - n;
double ln_mag = n * std::log(abs_alpha) - 0.5 * ln_n_fact;

return std::exp(ln_mag) * std::exp(1i * n * phase_alpha);

